import java.io.*;import java.nio.charset.StandardCharsets;import java.lang.reflect.*;import java.util.*;
import com.biglybt.pifimpl.local.utils.FormattersImpl;import com.biglybt.core.tag.*;import com.biglybt.core.category.Category;
// Calls actual source-pinned original comparator/sorter; no copied algorithm.
public final class OriginalTagStripOracle {
 static String string(DataInputStream in)throws Exception{int n=in.readInt();if(n<0)return null;if(n>65536)throw new IOException("Generated string bound");byte[] b=new byte[n];in.readFully(b);return new String(b,StandardCharsets.UTF_8);}
 public static void main(String[] args)throws Exception{DataInputStream in=new DataInputStream(System.in);DataOutputStream out=new DataOutputStream(System.out);Comparator<String> comparator=FormattersImpl.getAlphanumericComparator2(true);int n=in.readInt();if(n<0||n>4096)throw new IOException("Generated comparison bound");for(int i=0;i<n;i++)out.writeInt(Integer.signum(comparator.compare(string(in),string(in))));int rows=in.readInt();List<Tag> tags=new ArrayList<>();Map<Tag,Integer> ids=new IdentityHashMap<>();for(int i=0;i<rows;i++){final String name=string(in),group=string(in);final int kind=in.readInt(),id=i;Class<?> type=kind<0?Tag.class:Category.class;Tag tag=(Tag)Proxy.newProxyInstance(OriginalTagStripOracle.class.getClassLoader(),new Class[]{type},(p,m,a)->{switch(m.getName()){case "getTagName":return name;case "getGroup":return group;case "getType":return kind;case "getTagID":return id;case "getTagUID":return (long)id;case "hashCode":return System.identityHashCode(p);case "equals":return p==a[0];case "toString":return name;default:if(m.getReturnType()==boolean.class)return false;if(m.getReturnType()==int.class)return 0;if(m.getReturnType()==long.class)return 0L;return null;}});tags.add(tag);ids.put(tag,id);}List<Tag> sorted=TagUtils.sortTags(tags);out.writeInt(sorted.size());for(Tag tag:sorted)out.writeInt(ids.get(tag));out.flush();}
}
